content='''def transform(grid):
    h, w = len(grid), len(grid[0])
    wall = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), None)
    if wall is None:
        return [row[:] for row in grid]
    out = [[0] * w for _ in range(h)]
    out[wall] = grid[wall][:]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 4:
                continue
            if r < wall:
                landing = r + 1
                if landing < wall:
                    out[landing][c] = 4
                    # Last step to the barrier side causes a symmetric fan.
                    if landing == wall - 1:
                        for d in range(1, landing + 1):
                            rr = landing - d
                            for cc in (c - d, c + d):
                                if 0 <= cc < w:
                                    out[rr][cc] = 4
            else:
                # Lower markers move upward to the neighboring cell.
                if r > wall + 1:
                    out[r - 1][c] = 4
                else:
                    out[r][c] = 4
    return out
'''
